const bar = (x, y, w, h, v, col, lab) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="var(--sunk)" stroke="var(--line)"/><rect x="${x}" y="${y}" width="${Math.max(0, Math.min(1, v)) * w}" height="${h}" rx="3" fill="${col}" opacity="0.75"/>` + (lab ? tx(x - 6, y + h - 2, lab, "end") : "");
